#define CCM_ENABLE_ENABLE_Pos (0UL)                  /*!< Position of ENABLE field.                                            */
#define CCM_ENABLE_ENABLE_Msk (0x3UL << CCM_ENABLE_ENABLE_Pos) /*!< Bit mask of ENABLE field.                                  */
