#define MRAMC_INTENCLR_ECCERRORCORR_Disabled (0x0UL) /*!< Read: Disabled                                                       */
#define MRAMC_INTENCLR_ECCERRORCORR_Enabled (0x1UL)  /*!< Read: Enabled                                                        */

/* TRIMCONFIGREQ @Bit 4 : Write '1' to disable interrupt for event TRIMCONFIGREQ */
#define MRAMC_INTENCLR_TRIMCONFIGREQ_Pos (4UL)       /*!< Position of TRIMCONFIGREQ field.                                     */
#define MRAMC_INTENCLR_TRIMCONFIGREQ_Msk (0x1UL << MRAMC_INTENCLR_TRIMCONFIGREQ_Pos) /*!< Bit mask of TRIMCONFIGREQ field.     */
#define MRAMC_INTENCLR_TRIMCONFIGREQ_Clear (0x1UL)   /*!< Disable                                                              */
#define MRAMC_INTENCLR_TRIMCONFIGREQ_Disabled (0x0UL) /*!< Read: Disabled                                                      */
#define MRAMC_INTENCLR_TRIMCONFIGREQ_Enabled (0x1UL) /*!< Read: Enabled                                                        */

/* ACCESSERR @Bit 5 : Write '1' to disable interrupt for event ACCESSERR */
#define MRAMC_INTENCLR_ACCESSERR_Pos (5UL)           /*!< Position of ACCESSERR field.                                         */
#define MRAMC_INTENCLR_ACCESSERR_Msk (0x1UL << MRAMC_INTENCLR_ACCESSERR_Pos) /*!< Bit mask of ACCESSERR field.                 */
#define MRAMC_INTENCLR_ACCESSERR_Clear (0x1UL)       /*!< Disable                                                              */
#define MRAMC_INTENCLR_ACCESSERR_Disabled (0x0UL)    /*!< Read: Disabled                                                       */
#define MRAMC_INTENCLR_ACCESSERR_Enabled (0x1UL)     /*!< Read: Enabled                                                        */


/* MRAMC_READY: MRAMC status. */

/* READY @Bit 0 : MRAMC is ready or busy */
#define MRAMC_READY_READY_Pos (0UL)                  /*!< Position of READY field.                                             */
#define MRAMC_READY_READY_Msk (0x1UL << MRAMC_READY_READY_Pos) /*!< Bit mask of READY field.                                   */
#define MRAMC_READY_READY_Busy (0x0UL)               /*!< MRAMC is busy                                                        */
#define MRAMC_READY_READY_Ready (0x1UL)              /*!< Current operation is completed and MRAMC is ready                    */


/* MRAMC_READYNEXT: Ready next flag. */

/* READYNEXT @Bit 0 : MRAMC can accept a new write operation */
#define MRAMC_READYNEXT_READYNEXT_Pos (0UL)          /*!< Position of READYNEXT field.                                         */
#define MRAMC_READYNEXT_READYNEXT_Msk (0x1UL << MRAMC_READYNEXT_READYNEXT_Pos) /*!< Bit mask of READYNEXT field.               */
#define MRAMC_READYNEXT_READYNEXT_Busy (0x0UL)       /*!< MRAMC cannot accept any write operation                              */
#define MRAMC_READYNEXT_READYNEXT_Ready (0x1UL)      /*!< MRAMC is ready to accept a new write operation                       */


/* MRAMC_CONFIG: Configuration register */

/* WEN @Bit 0 : Write enable. */
#define MRAMC_CONFIG_WEN_Pos (0UL)                   /*!< Position of WEN field.                                               */
#define MRAMC_CONFIG_WEN_Msk (0x1UL << MRAMC_CONFIG_WEN_Pos) /*!< Bit mask of WEN field.                                       */
#define MRAMC_CONFIG_WEN_DisableWrite (0x0UL)        /*!< Write is disabled but read is allowed                                */
#define MRAMC_CONFIG_WEN_EnableWrite (0x1UL)         /*!< Write and read are allowed                                           */

/* EPEN @Bit 1 : Erase page enable. */
#define MRAMC_CONFIG_EPEN_Pos (1UL)                  /*!< Position of EPEN field.                                              */
#define MRAMC_CONFIG_EPEN_Msk (0x1UL << MRAMC_CONFIG_EPEN_Pos) /*!< Bit mask of EPEN field.                                    */
#define MRAMC_CONFIG_EPEN_DisableErase (0x0UL)       /*!< Erase page is disabled but read is allowed                           */
#define MRAMC_CONFIG_EPEN_EnableErase (0x1UL)        /*!< Erase page and read are allowed                                      */

/* EWEN @Bit 3 : Erase word enable. */
#define MRAMC_CONFIG_EWEN_Pos (3UL)                  /*!< Position of EWEN field.                                              */
#define MRAMC_CONFIG_EWEN_Msk (0x1UL << MRAMC_CONFIG_EWEN_Pos) /*!< Bit mask of EWEN field.                                    */
#define MRAMC_CONFIG_EWEN_DisableErase (0x0UL)       /*!< Erase word is disabled but read is allowed                           */
#define MRAMC_CONFIG_EWEN_EnableErase (0x1UL)        /*!< Erase word and read are allowed                                      */

/* DWEN @Bit 4 : Direct write enable. */
#define MRAMC_CONFIG_DWEN_Pos (4UL)                  /*!< Position of DWEN field.                                              */
#define MRAMC_CONFIG_DWEN_Msk (0x1UL << MRAMC_CONFIG_DWEN_Pos) /*!< Bit mask of DWEN field.                                    */
#define MRAMC_CONFIG_DWEN_DisableDirectWrite (0x0UL) /*!< Direct write is disabled but read is allowed                         */
#define MRAMC_CONFIG_DWEN_EnableDirectWrite (0x1UL)  /*!< Direct write and read are allowed                                    */

/* DISABLEECC @Bit 8 : Disable ECC. It is enabled by default */
#define MRAMC_CONFIG_DISABLEECC_Pos (8UL)            /*!< Position of DISABLEECC field.                                        */
#define MRAMC_CONFIG_DISABLEECC_Msk (0x1UL << MRAMC_CONFIG_DISABLEECC_Pos) /*!< Bit mask of DISABLEECC field.                  */
#define MRAMC_CONFIG_DISABLEECC_EnableECC (0x0UL)    /*!< Enable ECC                                                           */
#define MRAMC_CONFIG_DISABLEECC_DisableECC (0x1UL)   /*!< Disable ECC                                                          */


/* MRAMC_AUTOREADMODE: Automatically disables the write and erases on timeout and 
      enters into read mode. */

/* VALUE @Bits 0..11 : Timeout value to disable write and erase. */
#define MRAMC_AUTOREADMODE_VALUE_Pos (0UL)           /*!< Position of VALUE field.                                             */
#define MRAMC_AUTOREADMODE_VALUE_Msk (0xFFFUL << MRAMC_AUTOREADMODE_VALUE_Pos) /*!< Bit mask of VALUE field.                   */


/* MRAMC_WAITSTATES: Waitstates for MRAM read access */

/* WAITSTATENUM @Bits 0..4 : Register to read the current number of waitstate for the MRAM access and 
        set a new value
                             */                                                                                                   
                                                                                                                                  
#define MRAMC_WAITSTATES_WAITSTATENUM_Pos (0UL)      /*!< Position of WAITSTATENUM field.                                      */
#define MRAMC_WAITSTATES_WAITSTATENUM_Msk (0x1FUL << MRAMC_WAITSTATES_WAITSTATENUM_Pos) /*!< Bit mask of WAITSTATENUM field.   */

/* KEY @Bits 16..31 : Key to enable the writing to this register. */
#define MRAMC_WAITSTATES_KEY_Pos (16UL)              /*!< Position of KEY field.                                               */
#define MRAMC_WAITSTATES_KEY_Msk (0xFFFFUL << MRAMC_WAITSTATES_KEY_Pos) /*!< Bit mask of KEY field.                            */


/* MRAMC_READYNEXTTIMEOUT: Prelaod timeout value for waiting for a next write */

/* VALUE @Bits 0..11 : Preload value */
#define MRAMC_READYNEXTTIMEOUT_VALUE_Pos (0UL)       /*!< Position of VALUE field.                                             */
#define MRAMC_READYNEXTTIMEOUT_VALUE_Msk (0xFFFUL << MRAMC_READYNEXTTIMEOUT_VALUE_Pos) /*!< Bit mask of VALUE field.           */



