#define RADIO_DFECTRL1_TSWITCHSPACING_Msk (0x7UL << RADIO_DFECTRL1_TSWITCHSPACING_Pos) /*!< Bit mask of TSWITCHSPACING field.  */
#define RADIO_DFECTRL1_TSWITCHSPACING_8us (0x0UL)    /*!< 8us                                                                  */
