#define RADIO_DFECTRL1_TSWITCHSPACING_2us (0x2UL)    /*!< 2us                                                                  */
#define RADIO_DFECTRL1_TSWITCHSPACING_1us (0x3UL)    /*!< 1us                                                                  */
