#define RADIO_DFECTRL4_MAXTOTALSAMPLES_Msk (0xFFFUL << RADIO_DFECTRL4_MAXTOTALSAMPLES_Pos) /*!< Bit mask of MAXTOTALSAMPLES
                                                                            field.*/                                              


/* RADIO_DFECTRL5: Various hacker/tuning configuration for Direction finding */

/* SATURATIONMODE @Bits 16..17 : Set how input saturation will be present in the captured samples */
#define RADIO_DFECTRL5_SATURATIONMODE_Pos (16UL)     /*!< Position of SATURATIONMODE field.                                    */
#define RADIO_DFECTRL5_SATURATIONMODE_Msk (0x3UL << RADIO_DFECTRL5_SATURATIONMODE_Pos) /*!< Bit mask of SATURATIONMODE field.  */
#define RADIO_DFECTRL5_SATURATIONMODE_OFF (0x0UL)    /*!< No saturation is presented                                           */
