#define AAR_INTEN_NOTRESOLVED_Pos (2UL)              /*!< Position of NOTRESOLVED field.                                       */
#define AAR_INTEN_NOTRESOLVED_Msk (0x1UL << AAR_INTEN_NOTRESOLVED_Pos) /*!< Bit mask of NOTRESOLVED field.                     */
